input.command:
cd ~/.claude/plugins; grep -rl --include='*.json' '"dependencies"' marketplaces cache 2>/dev/null | grep -v node_modules | grep -v package | head; echo ---; python3 - <<'EOF'
import json
m=json.load(open('marketplaces/claude-plugins-official/.claude-plugin/marketplace.json'))
print(m.keys())
for p in m['plugins']:
  if 'dependencies' in p: print(p['name'], p['dependencies'])
keys=set()
for p in m['plugins']: keys|=set(p.keys())
print(keys)
EOF

