input.command:
cd /Users/trang.doan/Desktop/code/dgflow && cat > .claude-plugin/plugin.json <<'EOF'
{
  "$schema": "https://json.schemastore.org/claude-code-plugin-manifest.json",
  "name": "dgflow",
  "version": "0.1.0",
  "description": "Discourse Graphs team workflow for Claude Code: take a Linear ticket from a fresh worktree to a verified, reviewer-ready pull request.",
  "author": {
    "name": "Trang Doan"
  },
  "repository": "https://github.com/DiscourseGraphs/dgflow",
  "keywords": ["discourse-graphs", "workflow", "linear", "pull-requests", "roam", "obsidian"],
  "dependencies": ["mattpocock-skills@claude-plugins-official"]
}
EOF
cat > .claude-plugin/marketplace.json <<'EOF'
{
  "$schema": "https://anthropic.com/claude-code/marketplace.schema.json",
  "name": "dgflow",
  "owner": {
    "name": "DiscourseGraphs",
    "url": "https://github.com/DiscourseGraphs"
  },
  "metadata": {
    "description": "The Discourse Graphs team's Claude Code workflow plugin."
  },
  "allowCrossMarketplaceDependenciesOn": ["claude-plugins-official"],
  "plugins": [
    {
      "name": "dgflow",
      "source": "./",
      "description": "Discourse Graphs team workflow for Claude Code: take a Linear ticket from a fresh worktree to a verified, reviewer-ready pull request.",
      "category": "development"
    }
  ]
}
EOF
printf 'node_modules/\n.DS_Store\n*.log\n' > .gitignore
grep -o '"\$schema":"[^"]*"' ~/.claude/plugins/marketplaces/claude-plugins-official/.claude-plugin/marketplace.json | head -1; python3 -c "import json;json.load(open('/Users/trang.doan/.claude/plugins/marketplaces/claude-plugins-official/.claude-plugin/marketplace.json'))['\$schema'] and print(json.load(open('/Users/trang.doan/.claude/plugins/marketplaces/claude-plugins-official/.claude-plugin/marketplace.json'))['\$schema'])"

